+// React-style component for notification preferences form
+class NotificationForm {
+    constructor() {
+        this.state = {
+            selectedOption: null,
+            isSubmitted: false
+        };
+        this.render();
+    }
+
+    handleRadioChange(value) {
+        this.state.selectedOption = value;
+        this.updateRadioInputs();
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+        if (this.state.selectedOption) {
+            this.state.isSubmitted = true;
+            this.showSuccessMessage();
+            console.log('Form submitted with selection:', this.state.selectedOption);
+            setTimeout(() => {
+                this.state.isSubmitted = false;
+                this.render();
+            }, 2000);
+        }
+    }
+
+    showSuccessMessage() {
+        const message = document.querySelector('.success-message');
+        if (message) {
+            message.classList.add('show');
+        }
+    }
+
+    updateRadioInputs() {
+        const radios = document.querySelectorAll('input[name="notification-preference"]');
+        radios.forEach(radio => {
+            radio.checked = radio.value === this.state.selectedOption;
+        });
+    }
+
+    render() {
+        const root = document.getElementById('root');
+        
+        root.innerHTML = `
+            <div class="notification-form">
+                <h1 class="form-title">Notification Settings</h1>
+                
+                <form id="notification-form">
+                    <div class="form-field">
+                        <label class="form-field-label">How do you prefer to receive notifications?</label>
+                        
+                        <div class="radio-group">
+                            <label class="radio-option">
+                                <input 
+                                    type="radio" 
+                                    name="notification-preference" 
+                                    value="email"
+                                    ${this.state.selectedOption === 'email' ? 'checked' : ''}
+                                >
+                                <label>Email</label>
+                            </label>
+                            
+                            <label class="radio-option">
+                                <input 
+                                    type="radio" 
+                                    name="notification-preference" 
+                                    value="sms"
+                                    ${this.state.selectedOption === 'sms' ? 'checked' : ''}
+                                >
+                                <label>SMS</label>
+                            </label>
+                            
+                            <label class="radio-option">
+                                <input 
+                                    type="radio" 
+                                    name="notification-preference" 
+                                    value="push"
+                                    ${this.state.selectedOption === 'push' ? 'checked' : ''}
+                                >
+                                <label>Push Notifications</label>
+                            </label>
+                        </div>
+                    </div>
+                    
+                    <button 
+                        type="submit" 
+                        class="submit-button"
+                        ${this.state.isSubmitted ? 'disabled' : ''}
+                    >
+                        ${this.state.isSubmitted ? 'Saving...' : 'Save Preference'}
+                    </button>
+                    
+                    <div class="success-message ${this.state.isSubmitted ? 'show' : ''}">
+                        ✓ Preference saved successfully!
+                    </div>
+                </form>
+            </div>
+        `;
+
+        this.attachEventListeners();
+    }
+
+    attachEventListeners() {
+        const form = document.getElementById('notification-form');
+        const radios = document.querySelectorAll('input[name="notification-preference"]');
+
+        form.addEventListener('submit', (e) => this.handleSubmit(e));
+
+        radios.forEach(radio => {
+            radio.addEventListener('change', (e) => {
+                this.handleRadioChange(e.target.value);
+            });
+        });
+    }
+}
+
+// Initialize the component when DOM is ready
+document.addEventListener('DOMContentLoaded', () => {
+    new NotificationForm();
+});
